"use client";

import Image from "next/image";
import Link from "next/link";
import { useState, useEffect, useRef } from "react";
import { usePathname } from "next/navigation";
import Container from "@/components/ui/Container";

const navItems = [
    { label: "Home", href: "/" },
    { label: "About", href: "/about" },
    { label: "Services", href: "/services" },
    { label: "Projects", href: "/projects" },
    { label: "VR Experience", href: "/vr-experience" },
    { label: "Contact", href: "/contact" },
];

export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);
    const [isMounted, setIsMounted] = useState(false);
    const pathname = usePathname();

    const navRef = useRef<HTMLElement>(null);

    const handleLogoClick = (e: React.MouseEvent) => {
        setIsOpen(false);
        if (pathname === "/") {
            e.preventDefault();
            window.scrollTo({
                top: 0,
                behavior: "smooth"
            });
        }
    };

    // Manage mount state for exit animations
    useEffect(() => {
        if (isOpen) {
            setIsMounted(true);
        } else {
            const timer = setTimeout(() => setIsMounted(false), 240);
            return () => clearTimeout(timer);
        }
    }, [isOpen]);

    // Close on escape key
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === "Escape") setIsOpen(false);
        };
        window.addEventListener("keydown", handleKeyDown);
        return () => window.removeEventListener("keydown", handleKeyDown);
    }, []);

    // Close on outside click and scroll
    useEffect(() => {
        if (!isOpen) return;

        const handleOutsideClick = (e: PointerEvent | MouseEvent) => {
            if (navRef.current && !navRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };

        const handleScroll = () => {
            setIsOpen(false);
        };

        // Pointerdown is preferred for modern touch/mouse setups
        document.addEventListener("pointerdown", handleOutsideClick);
        document.addEventListener("mousedown", handleOutsideClick); // fallback
        window.addEventListener("scroll", handleScroll, { passive: true });

        return () => {
            document.removeEventListener("pointerdown", handleOutsideClick);
            document.removeEventListener("mousedown", handleOutsideClick);
            window.removeEventListener("scroll", handleScroll);
        };
    }, [isOpen]);

    return (
        <>
            {/* Full screen backdrop for mobile menu */}
            {isMounted && (
                <div
                    className={`fixed inset-0 z-40 bg-black/[0.03] backdrop-blur-[1px] lg:hidden transition-opacity ease-out motion-reduce:transition-none
                    ${isOpen ? "opacity-100 duration-300" : "opacity-0 duration-200"}`}
                    aria-hidden="true"
                    onClick={() => setIsOpen(false)}
                />
            )}

            <header ref={navRef} className="fixed left-0 right-0 top-5 z-50 w-full pointer-events-none">
                <Container className="relative pointer-events-auto">
                    <nav
                        className="
          flex w-full
          items-center justify-between
          rounded-full
          border border-white/70
          bg-white/75
          px-5 py-3
          shadow-[0_8px_30px_rgba(0,0,0,0.06)]
          backdrop-blur-2xl
        "
                    >
                        {/* Logo */}
                        <Link
                            href="/"
                            className="flex items-center z-50 lg:z-auto transition-transform duration-200 hover:scale-[1.02] active:scale-[0.97]"
                            onClick={handleLogoClick}
                        >
                            <Image
                                src="/image/logo/nm-logo.png"
                                alt="N&M Engineering Services & Construction"
                                width={200}
                                height={60}
                                priority
                                className="h-7 sm:h-8 lg:h-11 w-auto object-contain"
                            />
                        </Link>

                        {/* Navigation - Desktop */}
                        <div className="hidden items-center gap-2 lg:flex">
                            {navItems.map((item) => {
                                const isActive = pathname === item.href || (item.href !== "/" && pathname.startsWith(item.href));
                                return (
                                    <Link
                                        key={item.href}
                                        href={item.href}
                                        className={`
                                            relative px-3.5 py-2 text-sm font-medium transition-all duration-200 ease-out
                                            rounded-full motion-reduce:transition-none motion-reduce:transform-none
                                            hover:-translate-y-[1px] hover:scale-[1.01] active:scale-[0.97]
                                            focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-700/50
                                            ${isActive
                                                ? "text-red-700 bg-white/65 border border-white/75 backdrop-blur-md shadow-[0_4px_12px_rgba(0,0,0,0.03)]"
                                                : "text-neutral-600 hover:text-red-700 hover:bg-white/65 hover:border hover:border-white/75 hover:backdrop-blur-md hover:shadow-[0_4px_12px_rgba(0,0,0,0.03)] border border-transparent"}
                                        `}
                                    >
                                        {item.label}
                                    </Link>
                                );
                            })}
                        </div>

                        {/* CTA - Desktop */}
                        <Link
                            href="/contact"
                            className="
                hidden
                rounded-full bg-red-700
                px-5 py-2.5
                text-sm font-medium text-white
                transition-all duration-200 ease-out
                hover:bg-red-800 hover:-translate-y-[1px] hover:shadow-[0_8px_20px_rgba(185,28,28,0.22)]
                active:scale-[0.98]
                focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-700/50 focus-visible:ring-offset-2
                motion-reduce:transition-none motion-reduce:transform-none
                lg:inline-flex
              "
                        >
                            Book Consultation
                        </Link>

                        {/* Mobile Menu Button  */}
                        <button
                            className={`flex lg:hidden h-[42px] w-[42px] items-center justify-center rounded-full border shadow-sm text-neutral-800 transition-all duration-200 active:scale-95 z-50 
                            ${isOpen ? "bg-white border-neutral-200 shadow-md" : "bg-white/60 border-neutral-200/80 hover:bg-neutral-100"}`}
                            onClick={() => setIsOpen(!isOpen)}
                            aria-label={isOpen ? "Close menu" : "Open menu"}
                            aria-expanded={isOpen}
                        >
                            <div className="relative w-5 h-3.5 flex flex-col justify-between">
                                <span className="h-[2px] w-full bg-current rounded-full" />
                                <span className="h-[2px] w-full bg-current rounded-full" />
                                <span className="h-[2px] w-full bg-current rounded-full" />
                            </div>
                        </button>
                    </nav>

                    {/* Mobile Menu Dropdown */}
                    {isMounted && (
                        <div className={`absolute top-[calc(100%+16px)] left-4 right-4 sm:left-6 sm:right-6 lg:hidden flex flex-col overflow-y-auto overflow-x-hidden max-h-[calc(100vh-120px)] rounded-[24px] bg-white/75 border border-white/70 shadow-[0_20px_60px_rgba(0,0,0,0.08)] backdrop-blur-2xl p-6 transition-all ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none origin-top
                        ${isOpen ? "opacity-100 translate-y-0 scale-100 duration-300" : "opacity-0 -translate-y-2 scale-[0.98] duration-200"}`}>
                            <div className="flex flex-col space-y-1 w-full">
                                {navItems.map((item, idx) => {
                                    const isActive = pathname === item.href || (item.href !== "/" && pathname.startsWith(item.href));
                                    return (
                                        <Link
                                            key={item.href}
                                            href={item.href}
                                            onClick={() => setIsOpen(false)}
                                            className={`block w-full px-4 py-3.5 text-base font-semibold transition-all duration-200 ease-out motion-reduce:transition-none active:scale-[0.98] rounded-xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-700/50
                                            ${isActive
                                                    ? "text-red-700 bg-red-50/60 border border-red-100/50"
                                                    : "text-neutral-800 hover:text-red-700 hover:bg-red-50/40 border border-transparent"}
                                            ${isOpen ? "opacity-100 translate-y-0" : "opacity-0 translate-y-1"}`}
                                            style={{
                                                transitionDuration: "300ms",
                                                transitionDelay: isOpen ? `${idx * 25}ms` : "0ms",
                                            }}
                                        >
                                            {item.label}
                                        </Link>
                                    );
                                })}
                            </div>

                            <div className="my-5 h-px w-full bg-neutral-200/60" />

                            <Link
                                href="/contact"
                                onClick={() => setIsOpen(false)}
                                className={`w-full rounded-[20px] bg-red-700 py-4 text-center text-sm font-medium text-white transition-all active:scale-[0.98]
                                ${isOpen ? "opacity-100 translate-y-0" : "opacity-0 translate-y-1"}`}
                                style={{
                                    transitionDuration: "300ms",
                                    transitionDelay: isOpen ? `${navItems.length * 25}ms` : "0ms",
                                }}
                            >
                                Book a Consultation
                            </Link>
                        </div>
                    )}
                </Container>
            </header>
        </>
    );
}

