"use client";

import { useFrame } from "@react-three/fiber";
import { useGLTF, Html } from "@react-three/drei";
import { useRef, useMemo, useEffect, useState } from "react";
import * as THREE from "three";

export default function HouseModel({
    scrollProgress,
    isReducedMotion
}: {
    scrollProgress: React.MutableRefObject<number>,
    isReducedMotion: boolean
}) {
    const { scene } = useGLTF("/models/nm-house.glb");

    const modelRef = useRef<THREE.Group>(null);
    const roofMainRef = useRef<THREE.Object3D | null>(null);
    const roofLeftRef = useRef<THREE.Object3D | null>(null);
    const roofRightRef = useRef<THREE.Object3D | null>(null);

    // Store original Y positions so we can animate relative to them
    const originalRoofY = useRef<{ main: number, left: number, right: number }>({ main: 0, left: 0, right: 0 });

    useMemo(() => {
        scene.traverse((child) => {
            if (child.name === "Roof_Main") {
                roofMainRef.current = child;
                originalRoofY.current.main = child.position.y;
            }
            if (child.name === "Roof_Left") {
                roofLeftRef.current = child;
                originalRoofY.current.left = child.position.y;
            }
            if (child.name === "Roof_Right") {
                roofRightRef.current = child;
                originalRoofY.current.right = child.position.y;
            }

            // Add shadows and materials
            if ((child as THREE.Mesh).isMesh) {
                child.castShadow = true;
                child.receiveShadow = true;
                if ((child as THREE.Mesh).material) {
                    const mat = ((child as THREE.Mesh).material as THREE.MeshStandardMaterial).clone();
                    mat.envMapIntensity = 0.8;
                    (child as THREE.Mesh).material = mat;
                }
            }
        });
    }, [scene]);

    const currentRot = useRef(0);
    const currentRoofY = useRef(0);
    const currentCamDistance = useRef(15);

    // Smooth progress tracker for React state (HTML opacity driven by this to avoid constant re-renders)
    const [activeLabels, setActiveLabels] = useState<string[]>([]);

    // Just a flag to fix initial hydration jump
    const isReady = useRef(false);

    useFrame((state, delta) => {
        if (!isReady.current) {
            state.camera.position.set(0, 3, 15);
            state.camera.lookAt(0, 0, 0);
            isReady.current = true;
        }

        const progress = isReducedMotion ? 1 : scrollProgress.current;

        // --- HOUSE ROTATION ---
        // 0 -> 0 rad
        // 1.00 -> 110 deg (1.91 rad)
        const targetRot = progress * (110 * Math.PI / 180);
        currentRot.current = THREE.MathUtils.lerp(currentRot.current, targetRot, delta * 4.5);
        if (modelRef.current) {
            modelRef.current.rotation.y = currentRot.current;
            modelRef.current.rotation.x = THREE.MathUtils.lerp(modelRef.current.rotation.x, progress * 0.08, delta * 4.5);
        }

        // --- ROOF REVEAL ---
        // 40% - 65% lifts upward
        let roofTargetOffset = 0;
        if (progress > 0.4) {
            const roofProgress = Math.min(1, (progress - 0.4) / 0.25);
            roofTargetOffset = roofProgress * 6; // Lift 6 units up
        }
        currentRoofY.current = THREE.MathUtils.lerp(currentRoofY.current, roofTargetOffset, delta * 5);

        if (roofMainRef.current) roofMainRef.current.position.y = originalRoofY.current.main + currentRoofY.current;
        if (roofLeftRef.current) roofLeftRef.current.position.y = originalRoofY.current.left + currentRoofY.current;
        if (roofRightRef.current) roofRightRef.current.position.y = originalRoofY.current.right + currentRoofY.current;

        // --- CAMERA MOVEMENT ---
        // Start far, move closer around middle, slightly down towards end
        let camTargetDist = 15;
        let camTargetY = 3;

        if (progress > 0.5) {
            const zoomProgress = Math.min(1, (progress - 0.5) / 0.5);
            camTargetDist = 15 - (zoomProgress * 6); // Move from 15 to 9
            camTargetY = 3 - (zoomProgress * 1.5);   // Move from 3 to 1.5
        }

        state.camera.position.x = THREE.MathUtils.lerp(state.camera.position.x, 0, delta * 3);
        state.camera.position.y = THREE.MathUtils.lerp(state.camera.position.y, camTargetY, delta * 3);
        state.camera.position.z = THREE.MathUtils.lerp(state.camera.position.z, camTargetDist, delta * 3);
        state.camera.lookAt(0, 0, 0);

        // --- LABELS SYNC ---
        // We only trigger React state change sparingly
        const labelsToActivate = [];
        if (progress >= 0.25) labelsToActivate.push("Living Area");
        if (progress >= 0.45) labelsToActivate.push("Open Kitchen");
        if (progress >= 0.60) labelsToActivate.push("Bedroom");
        if (progress >= 0.75) labelsToActivate.push("Outdoor Deck");

        if (labelsToActivate.length !== activeLabels.length) {
            setActiveLabels(labelsToActivate);
        }
    });

    const labels = [
        { name: "Living Area", position: [1.5, 0.8, 1.5] as [number, number, number] },
        { name: "Open Kitchen", position: [-1.5, 0.8, 0.5] as [number, number, number] },
        { name: "Bedroom", position: [-1, 2.5, -2] as [number, number, number] },
        { name: "Outdoor Deck", position: [2.5, 0.5, -2.5] as [number, number, number] }
    ];

    return (
        <group ref={modelRef} dispose={null} position={[0, -1, 0]}>
            <primitive object={scene} />
            {labels.map((label, idx) => {
                const isVisible = activeLabels.includes(label.name);
                return (
                    <Html key={idx} position={label.position} center zIndexRange={[100, 0]}>
                        <div className={`px-4 py-2 bg-white/80 backdrop-blur-md rounded-full shadow-sm text-xs font-semibold text-neutral-600 border border-neutral-100 whitespace-nowrap transition-all duration-700 ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2 pointer-events-none'}`}>
                            {label.name}
                        </div>
                    </Html>
                )
            })}
        </group>
    );
}

useGLTF.preload("/models/nm-house.glb");

